const data3 = $('Get Last 3d').first().json || {};
const data7 = $('Get Last 7d').first().json || {};

const esc = s => String(s == null ? '' : s)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

const money = n => {
  const v = Number(n || 0);
  return '$' + (Math.abs(v) >= 1000 ? v.toFixed(0).replace(/\B(?=(\d{3})+(?!\d))/g, ',') : v.toFixed(0));
};
const pct = n => {
  const v = Number(n || 0) * 100;
  const sign = v >= 0 ? '+' : '';
  return sign + v.toFixed(1) + '%';
};
const num = n => Math.round(Number(n || 0));

const trimName = n => {
  const s = String(n || '');
  return s.length > 42 ? s.slice(0, 41) + '\u2026' : s;
};

const icon = (i) => i === 0 ? '\uD83E\uDD47' : i === 1 ? '\uD83E\uDD48' : i === 2 ? '\uD83E\uDD49' : '\u2022';

const section = (label, data, topN = 8) => {
  const offers = (data.offers || []);
  const t = data.totals || { cost: 0, profit: 0, conversions: 0, roi: 0, cpa: 0 };
  if (!offers.length) {
    return '<b>' + label + '</b>\n<i>No active offers in window.</i>';
  }
  const top = offers.slice(0, topN);
  const rest = Math.max(0, offers.length - topN);
  const lines = top.map((o, i) => {
    const name = trimName(o.campaign_name);
    const v = o.vertical ? ' <i>(' + esc(o.vertical) + ')</i>' : '';
    return icon(i) + ' <b>' + esc(name) + '</b>' + v + '\n   '
      + 'Spend ' + money(o.cost) + '  \u00b7  Conv ' + num(o.conversions)
      + '  \u00b7  CPA ' + money(o.cpa) + '  \u00b7  ROI ' + pct(o.roi);
  });
  let out = '<b>' + label + '</b>  <i>(' + offers.length + ' offers)</i>\n' + lines.join('\n');
  if (rest > 0) out += '\n<i>\u2026 +' + rest + ' more</i>';
  out += '\n<b>Totals:</b> Spend ' + money(t.cost) + '  \u00b7  Profit ' + money(t.profit)
    + '  \u00b7  Conv ' + num(t.conversions) + '  \u00b7  ROI ' + pct(t.roi);
  return out;
};

const dateStr = new Date().toLocaleDateString('en-US', {
  timeZone: 'America/New_York',
  month: 'short', day: 'numeric', year: 'numeric'
});

const header = '\uD83D\uDCCA <b>Ad Performance Summary</b>\n\uD83D\uDCC5 ' + dateStr + ' (ET)';
const divider = '\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500';

const body = [
  header,
  divider,
  section('\uD83D\uDCC8 LAST 3 DAYS', data3),
  divider,
  section('\uD83D\uDCC8 LAST 7 DAYS', data7)
].join('\n\n');

let text = body;
if (text.length > 4000) {
  text = text.slice(0, 3990) + '\u2026';
}

return [{ json: { chat_id: $env.TELEGRAM_CHAT_ID, text, parse_mode: 'HTML', disable_web_page_preview: true } }];
